class Solution {
public:
    int minMaxGame(std::vector<int>& nums) {
        while (nums.size() > 1) {
            int n = nums.size() / 2;
            std::vector<int> next_nums(n);
            for (int i = 0; i < n; ++i) {
                if (i % 2 == 0) {
                    next_nums[i] = std::min(nums[2 * i], nums[2 * i + 1]);
                } else {
                    next_nums[i] = std::max(nums[2 * i], nums[2 * i + 1]);
                }
            }
            nums = std::move(next_nums);
        }
        return nums[0];
    }
};

class Solution {
    public int minMaxGame(int[] nums) {
        while (nums.length > 1) {
            int n = nums.length / 2;
            int[] next = new int[n];
            for (int i = 0; i < n; i++) {
                if (i % 2 == 0) {
                    next[i] = Math.min(nums[2 * i], nums[2 * i + 1]);
                } else {
                    next[i] = Math.max(nums[2 * i], nums[2 * i + 1]);
                }
            }
            nums = next;
        }
        return nums[0];
    }
}

